import React, { useState } from 'react';
import { Routes, Route, NavLink, useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
    LayoutDashboard, Package, Users, Truck, DollarSign,
    Settings, Menu, X, Bell, Moon, Sun, User, BarChart3,
    ShoppingCart, LogOut, TrendingUp
} from 'lucide-react';
import { useTheme } from '../../context/ThemeContext';
import { useAuth } from '../../context/AuthContext';
import AdminOverview from './AdminOverview';
import ProductManagement from './ProductManagement';
import AdSetup from './AdSetup';
import SalesRepManagement from './SalesRepManagement';
import DispatchPartnerManagement from './DispatchPartnerManagement';
import PaymentSettings from './PaymentSettings';
import CommissionSettings from './CommissionSettings';

const navigation = [
    { path: '/admin/dashboard', icon: LayoutDashboard, label: 'Overview', end: true },
    { path: '/admin/dashboard/products', icon: Package, label: 'Products' },
    { path: '/admin/dashboard/ads', icon: BarChart3, label: 'Ad Setup' },
    { path: '/admin/dashboard/sales-reps', icon: Users, label: 'Sales Reps' },
    { path: '/admin/dashboard/dispatch', icon: Truck, label: 'Dispatch' },
    { path: '/admin/dashboard/orders', icon: ShoppingCart, label: 'Orders' },
    { path: '/admin/dashboard/payments', icon: DollarSign, label: 'Payments' },
    { path: '/admin/dashboard/commissions', icon: TrendingUp, label: 'Commissions' },
];

const AdminDashboard = () => {
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const { isDark, toggleTheme } = useTheme();
    const { user, logout } = useAuth();
    const navigate = useNavigate();

    const handleLogout = () => {
        logout();
        navigate('/login');
    };

    return (
        <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
            {/* Mobile Sidebar Overlay */}
            <AnimatePresence>
                {sidebarOpen && (
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 bg-black/50 z-40 lg:hidden"
                        onClick={() => setSidebarOpen(false)}
                    />
                )}
            </AnimatePresence>

            {/* Sidebar */}
            <aside className={`
        fixed top-0 left-0 z-50 h-full w-64 bg-white dark:bg-gray-800 border-r border-gray-200 dark:border-gray-700
        transform transition-transform duration-200 ease-in-out overflow-y-auto
        ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}
        lg:translate-x-0 lg:static lg:z-auto
      `}>
                <div className="flex flex-col h-full">
                    {/* Logo */}
                    <div className="flex items-center justify-between p-4 border-b border-gray-200 dark:border-gray-700">
                        <div className="flex items-center gap-2">
                            <div className="h-8 w-8 rounded-lg bg-indigo-600 flex items-center justify-center">
                                <Package className="h-5 w-5 text-white" />
                            </div>
                            <div>
                                <span className="font-bold text-gray-900 dark:text-white">SalesPro</span>
                                <p className="text-xs text-gray-500">Admin Panel</p>
                            </div>
                        </div>
                        <button
                            onClick={() => setSidebarOpen(false)}
                            className="lg:hidden p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg"
                        >
                            <X className="h-5 w-5 text-gray-500" />
                        </button>
                    </div>

                    {/* Navigation */}
                    <nav className="flex-1 p-3 space-y-1 overflow-y-auto">
                        {navigation.map((item) => (
                            <NavLink
                                key={item.path}
                                to={item.path}
                                end={item.end}
                                onClick={() => setSidebarOpen(false)}
                                className={({ isActive }) => `
                  flex items-center gap-3 px-3 py-2.5 rounded-lg transition-colors text-sm font-medium
                  ${isActive
                                        ? 'bg-indigo-50 text-indigo-700 dark:bg-indigo-900/20 dark:text-indigo-400'
                                        : 'text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700'
                                    }
                `}
                            >
                                <item.icon className="h-5 w-5 flex-shrink-0" />
                                <span>{item.label}</span>
                            </NavLink>
                        ))}
                    </nav>

                    {/* User Info */}
                    <div className="p-4 border-t border-gray-200 dark:border-gray-700">
                        <div className="flex items-center gap-3 mb-3">
                            <div className="h-10 w-10 rounded-full bg-indigo-100 dark:bg-indigo-900/30 flex items-center justify-center flex-shrink-0">
                                <User className="h-5 w-5 text-indigo-600 dark:text-indigo-400" />
                            </div>
                            <div className="flex-1 min-w-0">
                                <p className="text-sm font-medium text-gray-900 dark:text-white truncate">
                                    {user?.firstName} {user?.lastName}
                                </p>
                                <p className="text-xs text-gray-500 dark:text-gray-400">Administrator</p>
                            </div>
                        </div>
                        <button
                            onClick={handleLogout}
                            className="w-full flex items-center gap-2 px-3 py-2 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors"
                        >
                            <LogOut className="h-4 w-4" />
                            Sign Out
                        </button>
                    </div>
                </div>
            </aside>

            {/* Main Content Area */}
            <div className="lg:pl-64">
                {/* Top Bar */}
                <header className="sticky top-0 z-30 bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700">
                    <div className="flex items-center justify-between px-4 h-16">
                        <button
                            onClick={() => setSidebarOpen(true)}
                            className="lg:hidden p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg"
                        >
                            <Menu className="h-5 w-5 text-gray-500" />
                        </button>

                        <div className="flex-1 lg:flex-none">
                            <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
                                Admin Dashboard
                            </h2>
                        </div>

                        <div className="flex items-center gap-2">
                            <button className="relative p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg">
                                <Bell className="h-5 w-5 text-gray-500" />
                                <span className="absolute top-1.5 right-1.5 h-2 w-2 bg-rose-500 rounded-full"></span>
                            </button>

                            <button
                                onClick={toggleTheme}
                                className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg"
                                title="Toggle theme"
                            >
                                {isDark ? (
                                    <Sun className="h-5 w-5 text-gray-500" />
                                ) : (
                                    <Moon className="h-5 w-5 text-gray-500" />
                                )}
                            </button>
                        </div>
                    </div>
                </header>

                {/* Page Content */}
                <main className="p-6">
                    <Routes>
                        <Route index element={<AdminOverview />} />
                        <Route path="products" element={<ProductManagement />} />
                        <Route path="ads" element={<AdSetup />} />
                        <Route path="sales-reps" element={<SalesRepManagement />} />
                        <Route path="dispatch" element={<DispatchPartnerManagement />} />
                        <Route path="orders" element={<OrdersPlaceholder />} />
                        <Route path="payments" element={<PaymentSettings />} />
                        <Route path="commissions" element={<CommissionSettings />} />
                        <Route path="*" element={<AdminOverview />} />
                    </Routes>
                </main>
            </div>
        </div>
    );
};

